  const qx = x / sh.sx, qz = (z - sh.lean) / sh.sz;
  const a = Math.atan2(qx, qz);
  let d = (Math.hypot(qx, qz) - radAt(a, y, brFast(y))) * Math.min(sh.sx, sh.sz);
